-- ==== 20260924000100_profiles.sql
-- Profiles: one row per auth user, created automatically on signup.

-- Shared helper: keep updated_at current on every UPDATE.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- True for region-style IANA zone names (e.g. 'America/Chicago') and 'UTC'. Rejects
-- abbreviations like 'EST' and fixed offsets like 'Etc/GMT+5', which don't follow the
-- daylight saving rules of any real place. Marked immutable so it can be
-- used in a CHECK; the zone list only changes with Postgres tzdata updates.
create or replace function public.is_valid_timezone(tz text)
returns boolean
language sql
immutable
parallel safe
set search_path = ''
as $$
  select tz is not null
    and (tz = 'UTC' or (tz ~ '^[A-Za-z_]+(/[A-Za-z0-9_+-]+)+$' and tz !~ '^Etc/'))
    and exists (select 1 from pg_catalog.pg_timezone_names where name = tz);
$$;

create type public.plan_tier as enum ('free', 'pro');

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text check (char_length(display_name) <= 100),
  timezone text not null default 'UTC' check (public.is_valid_timezone(timezone)),
  school text check (char_length(school) <= 200),
  -- Cached entitlement. Written only by the service role (billing webhooks);
  -- clients cannot update this column (see column grants below).
  plan_tier public.plan_tier not null default 'free',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on column public.profiles.timezone is
  'IANA timezone used to compute the user''s local day, default due times, and quiet hours.';

alter table public.profiles enable row level security;

create trigger profiles_set_updated_at
before update on public.profiles
for each row execute function public.set_updated_at();

create policy "Users can view their own profile"
on public.profiles for select
to authenticated
using ((select auth.uid()) = id);

create policy "Users can update their own profile"
on public.profiles for update
to authenticated
using ((select auth.uid()) = id)
with check ((select auth.uid()) = id);

-- Clients may only edit these columns; everything else is server-managed.
revoke insert, update on public.profiles from anon, authenticated;
grant update (display_name, timezone, school) on public.profiles to authenticated;

-- Create a profile whenever a user signs up. The client may pass its detected
-- timezone as user metadata ({ "timezone": "America/Chicago" }); invalid values
-- fall back to UTC instead of failing the signup.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  tz text := new.raw_user_meta_data ->> 'timezone';
begin
  insert into public.profiles (id, display_name, timezone, school)
  values (
    new.id,
    left(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), 100),
    case when public.is_valid_timezone(tz) then tz else 'UTC' end,
    left(nullif(trim(new.raw_user_meta_data ->> 'school'), ''), 200)
  );
  return new;
end;
$$;

revoke execute on function public.handle_new_user() from public, anon, authenticated;

create trigger on_auth_user_created
after insert on auth.users
for each row execute function public.handle_new_user();

-- ==== 20260924000200_courses_assignments_sessions.sql
-- Core academic schema: courses, their grade categories and assignments, and the
-- study sessions a student logs against them. RLS is enabled here (deny-all);
-- policies are added in the RLS migration.

create table public.courses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  name text not null check (char_length(trim(name)) between 1 and 200),
  code text check (char_length(code) <= 50),
  instructor text check (char_length(instructor) <= 200),
  -- Calendar dates in the user's timezone (no time component).
  term_start date,
  term_end date,
  -- Grade the student is aiming for, as a percentage.
  target_grade numeric(5, 2),
  color text check (color ~ '^#[0-9A-Fa-f]{6}$'),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint courses_term_order check (term_end is null or term_start is null or term_end >= term_start)
);

create index courses_user_id_idx on public.courses (user_id);

create table public.grade_categories (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  name text not null check (char_length(trim(name)) between 1 and 100),
  -- Share of the final grade, as a percentage.
  weight numeric(5, 2) not null,
  position smallint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint grade_categories_course_name_key unique (course_id, name),
  -- Target for composite foreign keys that keep children within one course.
  constraint grade_categories_id_course_key unique (id, course_id)
);

create type public.assignment_kind as enum (
  'assignment', 'quiz', 'exam', 'project', 'reading', 'lab', 'discussion', 'other'
);

create table public.assignments (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  -- Nullable: parsed assignments may not map to a category, and deleting a
  -- category keeps its assignments.
  category_id uuid,
  title text not null check (char_length(trim(title)) between 1 and 300),
  description text,
  kind public.assignment_kind not null default 'assignment',
  due_at timestamptz,
  status text not null default 'todo',
  completed_at timestamptz,
  points_earned numeric(8, 2),
  points_possible numeric(8, 2),
  -- Student's estimate of total effort, used for ranking and scheduling.
  estimated_minutes integer,
  source text not null default 'manual' check (source in ('manual', 'syllabus', 'canvas')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint assignments_id_course_key unique (id, course_id),
  -- The category must belong to the same course. Deleting it only clears category_id.
  constraint assignments_category_fkey foreign key (category_id, course_id)
    references public.grade_categories (id, course_id)
    on delete set null (category_id)
);

create index assignments_course_id_idx on public.assignments (course_id);
create index assignments_category_id_idx on public.assignments (category_id);
create index assignments_course_due_idx on public.assignments (course_id, due_at);

create table public.study_sessions (
  -- Clients may supply the id so retries of "start session" are idempotent.
  id uuid primary key default gen_random_uuid(),
  -- Denormalized owner so per-user queries and overlap checks don't need a join.
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  course_id uuid not null references public.courses (id) on delete cascade,
  assignment_id uuid references public.assignments (id) on delete set null,
  started_at timestamptz not null,
  -- Null while the session is running.
  ended_at timestamptz,
  duration_minutes integer generated always as (
    case when ended_at is null then null
    else floor(extract(epoch from (ended_at - started_at)) / 60)::integer end
  ) stored,
  source text not null default 'timer' check (source in ('timer', 'manual')),
  notes text check (char_length(notes) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index study_sessions_user_started_idx on public.study_sessions (user_id, started_at desc);
create index study_sessions_course_id_idx on public.study_sessions (course_id);
create index study_sessions_assignment_id_idx on public.study_sessions (assignment_id);

alter table public.courses enable row level security;
alter table public.grade_categories enable row level security;
alter table public.assignments enable row level security;
alter table public.study_sessions enable row level security;

create trigger courses_set_updated_at before update on public.courses
for each row execute function public.set_updated_at();
create trigger grade_categories_set_updated_at before update on public.grade_categories
for each row execute function public.set_updated_at();
create trigger assignments_set_updated_at before update on public.assignments
for each row execute function public.set_updated_at();
create trigger study_sessions_set_updated_at before update on public.study_sessions
for each row execute function public.set_updated_at();

-- ==== 20260924000300_rls_policies.sql
-- Owner-only row level security. Courses are owned directly through user_id;
-- child tables (grade_categories, assignments, study_sessions) are owned through
-- their course. Policies target `authenticated` only, so `anon` sees nothing.

-- Helpers live in a schema PostgREST doesn't expose, so they can't be called as RPCs.
create schema if not exists private;
grant usage on schema private to authenticated, service_role;

-- True when the current user owns the course. Security definer so the lookup
-- doesn't re-enter courses' own RLS for every child row; the result only ever
-- depends on auth.uid(), so it reveals nothing about other users.
create or replace function private.owns_course(course_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.courses c
    where c.id = owns_course.course_id
      and c.user_id = (select auth.uid())
  );
$$;

revoke execute on function private.owns_course(uuid) from public, anon;
grant execute on function private.owns_course(uuid) to authenticated, service_role;

