-- ==== 20260924000400_check_constraints.sql
-- Data integrity rules enforced in the database, so no client or job can bypass them.

-- Weights and targets are percentages.
alter table public.grade_categories
  add constraint grade_categories_weight_range check (weight >= 0 and weight <= 100);

alter table public.courses
  add constraint courses_target_grade_range check (target_grade is null or (target_grade >= 0 and target_grade <= 100));

-- Assignment status becomes a real enum.
create type public.assignment_status as enum ('todo', 'in_progress', 'done', 'skipped');

alter table public.assignments alter column status drop default;
alter table public.assignments
  alter column status type public.assignment_status using status::public.assignment_status;
alter table public.assignments alter column status set default 'todo';

-- Effort estimates are positive and sane (at most ~1 week of work).
alter table public.assignments
  add constraint assignments_estimated_minutes_range
  check (estimated_minutes is null or (estimated_minutes > 0 and estimated_minutes <= 10080));

-- Scores: points_possible is positive; points_earned is non-negative and needs a
-- points_possible to be meaningful. Earned may exceed possible (extra credit) up to
-- 2x, which catches typos like 950/100 without blocking real bonus points.
alter table public.assignments
  add constraint assignments_points_possible_positive
  check (points_possible is null or points_possible > 0),
  add constraint assignments_points_earned_range
  check (
    points_earned is null
    or (points_possible is not null and points_earned >= 0 and points_earned <= points_possible * 2)
  );

-- Keep completed_at in step with status so reports can rely on either.
create or replace function public.sync_assignment_completed_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'done' and new.completed_at is null then
    new.completed_at := now();
  elsif new.status <> 'done' then
    new.completed_at := null;
  end if;
  return new;
end;
$$;

create trigger assignments_sync_completed_at
before insert or update of status, completed_at on public.assignments
for each row execute function public.sync_assignment_completed_at();

-- Study sessions must have a positive duration of at most 24 hours once ended.
alter table public.study_sessions
  add constraint study_sessions_positive_duration
  check (ended_at is null or ended_at > started_at),
  add constraint study_sessions_max_duration
  check (ended_at is null or ended_at - started_at <= interval '24 hours');

-- ==== 20260924000500_study_session_consistency.sql
-- A study session's course must match its assignment's course, and its user must
-- own that course. RLS already stops clients from crossing users, but this also
-- covers service-role writers (jobs, imports) and catches same-user mix-ups.
-- If only assignment_id is given, course_id is filled in from the assignment.

create or replace function public.check_study_session_consistency()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  assignment_course uuid;
  course_owner uuid;
begin
  if new.assignment_id is not null then
    select a.course_id into assignment_course
    from public.assignments a
    where a.id = new.assignment_id;

    if assignment_course is null then
      raise exception 'assignment % does not exist', new.assignment_id
        using errcode = 'foreign_key_violation';
    end if;

    if new.course_id is null then
      new.course_id := assignment_course;
    elsif new.course_id <> assignment_course then
      raise exception 'study session course % does not match assignment course %',
        new.course_id, assignment_course
        using errcode = 'check_violation',
              hint = 'Omit course_id to use the assignment''s course.';
    end if;
  end if;

  select c.user_id into course_owner from public.courses c where c.id = new.course_id;
  if course_owner is distinct from new.user_id then
    raise exception 'study session user does not own course %', new.course_id
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

create trigger study_sessions_check_consistency
before insert or update of course_id, assignment_id, user_id on public.study_sessions
for each row execute function public.check_study_session_consistency();

-- Moving an assignment to another course would strand its sessions; carry them along.
create or replace function public.move_sessions_with_assignment()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.study_sessions
  set course_id = new.course_id
  where assignment_id = new.id;
  return new;
end;
$$;

create trigger assignments_move_sessions
after update of course_id on public.assignments
for each row
when (old.course_id is distinct from new.course_id)
execute function public.move_sessions_with_assignment();

-- ==== 20260924000600_syllabus_uploads.sql
-- Syllabus uploads and their parse results, plus the private storage bucket that
-- holds the original files. Files live at `syllabi/{user_id}/{upload_id}.{ext}`.

create type public.syllabus_source as enum ('pdf', 'image', 'text', 'url');
create type public.syllabus_upload_status as enum ('pending', 'processing', 'parsed', 'committed', 'failed');

create table public.syllabus_uploads (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  source public.syllabus_source not null,
  -- Storage object path inside the `syllabi` bucket (file sources only).
  file_path text check (file_path is null or file_path ~ '^[0-9a-f-]{36}/[^/]+$'),
  original_filename text check (char_length(original_filename) <= 255),
  mime_type text,
  size_bytes integer check (size_bytes is null or size_bytes > 0),
  source_url text check (source_url is null or source_url ~ '^https?://'),
  status public.syllabus_upload_status not null default 'pending',
  -- Validated parser output (see packages/core/parser). Null until parsed.
  parse_result jsonb,
  -- Human-readable failure reason when status = 'failed'.
  error text,
  -- Parser prompt + schema version that produced parse_result, for evals and reparsing.
  prompt_version text,
  model text,
  -- Set once the parse is committed into real rows.
  course_id uuid references public.courses (id) on delete set null,
  parsed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint syllabus_uploads_source_fields check (
    case source
      when 'pdf' then file_path is not null
      when 'image' then file_path is not null
      when 'url' then source_url is not null
      else true
    end
  ),
  constraint syllabus_uploads_file_in_own_folder check (
    file_path is null or split_part(file_path, '/', 1) = user_id::text
  ),
  constraint syllabus_uploads_failed_has_error check (status <> 'failed' or error is not null),
  constraint syllabus_uploads_parsed_has_result check (
    status not in ('parsed', 'committed') or parse_result is not null
  )
);

create index syllabus_uploads_user_created_idx on public.syllabus_uploads (user_id, created_at desc);

alter table public.syllabus_uploads enable row level security;

create trigger syllabus_uploads_set_updated_at before update on public.syllabus_uploads
for each row execute function public.set_updated_at();

-- Uploads are created and advanced by edge functions (service role), which validate
-- the file and run the parser. Clients can read and delete their own.
create policy "Users can view their own syllabus uploads"
on public.syllabus_uploads for select to authenticated
using ((select auth.uid()) = user_id);

create policy "Users can delete their own syllabus uploads"
on public.syllabus_uploads for delete to authenticated
using ((select auth.uid()) = user_id);

revoke all on public.syllabus_uploads from anon;
revoke insert, update on public.syllabus_uploads from authenticated;

-- Storage ------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'syllabi',
  'syllabi',
  false,
  20 * 1024 * 1024,
  array['application/pdf', 'image/png', 'image/jpeg', 'image/heic', 'image/webp']
)
on conflict (id) do update
set public = excluded.public,
    file_size_limit = excluded.file_size_limit,
    allowed_mime_types = excluded.allowed_mime_types;

-- Each user may only touch objects under their own `{user_id}/` folder.
create policy "Users can read their own syllabus files"
on storage.objects for select to authenticated
using (bucket_id = 'syllabi' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "Users can upload syllabus files to their own folder"
on storage.objects for insert to authenticated
with check (bucket_id = 'syllabi' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "Users can delete their own syllabus files"
on storage.objects for delete to authenticated
using (bucket_id = 'syllabi' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- ==== 20260924000700_study_blocks.sql
-- Study blocks: planned study time on the calendar, produced by the scheduler,
-- the exam review planner, or the user. A block is `planned` until it is marked
-- `done` or the nightly job marks it `missed`.

create type public.study_block_status as enum ('planned', 'done', 'missed');
create type public.study_block_kind as enum ('study', 'exam_prep', 'review');

create table public.study_blocks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  course_id uuid not null references public.courses (id) on delete cascade,
  assignment_id uuid references public.assignments (id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  duration_minutes integer generated always as (
    floor(extract(epoch from (ends_at - starts_at)) / 60)::integer
  ) stored,
  status public.study_block_status not null default 'planned',
  kind public.study_block_kind not null default 'study',
  source text not null default 'scheduler' check (source in ('scheduler', 'review_plan', 'manual')),
  -- User-placed or user-moved blocks are never moved by the rescheduler.
  locked boolean not null default false,
  -- When the rescheduler replaces a missed block, the new block points at the old one.
  rescheduled_from uuid references public.study_blocks (id) on delete set null,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint study_blocks_positive_duration check (ends_at > starts_at),
  constraint study_blocks_max_duration check (ends_at - starts_at <= interval '12 hours')
);

create index study_blocks_user_starts_idx on public.study_blocks (user_id, starts_at);
create index study_blocks_assignment_idx on public.study_blocks (assignment_id);
create index study_blocks_course_idx on public.study_blocks (course_id);
-- The nightly job scans planned blocks that have already ended.
create index study_blocks_planned_ends_idx on public.study_blocks (ends_at) where status = 'planned';

alter table public.study_blocks enable row level security;

create trigger study_blocks_set_updated_at before update on public.study_blocks
for each row execute function public.set_updated_at();

-- Same rules as study sessions: course matches the assignment's, user owns the course.
create trigger study_blocks_check_consistency
before insert or update of course_id, assignment_id, user_id on public.study_blocks
for each row execute function public.check_study_session_consistency();

create or replace function public.sync_study_block_completed_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'done' and new.completed_at is null then
    new.completed_at := now();
  elsif new.status <> 'done' then
    new.completed_at := null;
  end if;
  return new;
end;
$$;

create trigger study_blocks_sync_completed_at
before insert or update of status, completed_at on public.study_blocks
for each row execute function public.sync_study_block_completed_at();

-- Moving an assignment to another course carries its blocks along, like sessions.
create or replace function public.move_sessions_with_assignment()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.study_sessions set course_id = new.course_id where assignment_id = new.id;
  update public.study_blocks set course_id = new.course_id where assignment_id = new.id;
  return new;
end;
$$;

create policy "Users can view their own study blocks"
on public.study_blocks for select to authenticated
using ((select auth.uid()) = user_id and (select private.owns_course(course_id)));

create policy "Users can create study blocks in their courses"
on public.study_blocks for insert to authenticated
with check ((select auth.uid()) = user_id and (select private.owns_course(course_id)));

create policy "Users can update their own study blocks"
on public.study_blocks for update to authenticated
using ((select auth.uid()) = user_id and (select private.owns_course(course_id)))
with check ((select auth.uid()) = user_id and (select private.owns_course(course_id)));

create policy "Users can delete their own study blocks"
on public.study_blocks for delete to authenticated
using ((select auth.uid()) = user_id and (select private.owns_course(course_id)));

revoke all on public.study_blocks from anon;

-- ==== 20260924000800_notifications.sql
-- Notification delivery: device tokens, per-user preferences, and a log of every
-- send attempt (used for dedupe, daily caps, and debugging).

create type public.push_provider as enum ('expo', 'web_push');
create type public.notification_channel as enum ('expo', 'web_push', 'email');
create type public.notification_kind as enum (
  'due_24h', 'due_2h', 'exam_countdown', 'morning_digest', 'email_digest', 'overload_warning'
);
create type public.notification_status as enum ('sent', 'failed', 'skipped');

-- Tokens ----------------------------------------------------------------------

create table public.notification_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  provider public.push_provider not null,
  -- Expo push token, or the web push endpoint URL.
  token text not null check (char_length(token) between 1 and 2048),
  -- Web push only: { "p256dh": "...", "auth": "..." }.
  web_push_keys jsonb,
  platform text not null check (platform in ('ios', 'android', 'web')),
  device_id text check (char_length(device_id) <= 200),
  app_version text check (char_length(app_version) <= 50),
  last_seen_at timestamptz not null default now(),
  -- Set when the provider reports the token dead; invalid tokens are never used.
  invalidated_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- A device token belongs to exactly one account at a time.
  constraint notification_tokens_provider_token_key unique (provider, token),
  constraint notification_tokens_web_push_keys check (
    provider <> 'web_push'
    -- coalesce: a NULL result would otherwise pass the check.
    or coalesce(web_push_keys ? 'p256dh' and web_push_keys ? 'auth' and token ~ '^https://', false)
  )
);

create index notification_tokens_user_idx on public.notification_tokens (user_id)
where invalidated_at is null;

-- Preferences -----------------------------------------------------------------

create table public.notification_prefs (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  push_enabled boolean not null default true,
  email_digest_enabled boolean not null default false,
  remind_24h boolean not null default true,
  remind_2h boolean not null default true,
  exam_countdown boolean not null default true,
  morning_digest boolean not null default true,
  -- Local wall-clock times, interpreted in profiles.timezone.
  morning_digest_time time not null default '07:30',
  quiet_hours_enabled boolean not null default true,
  quiet_hours_start time not null default '22:00',
  quiet_hours_end time not null default '07:00',
  -- Upper bound on pushes per local day.
  daily_cap smallint not null default 6 check (daily_cap between 1 and 50),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Log --------------------------------------------------------------------------

create table public.notification_log (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind public.notification_kind not null,
  channel public.notification_channel not null,
  status public.notification_status not null,
  assignment_id uuid references public.assignments (id) on delete set null,
  token_id uuid references public.notification_tokens (id) on delete set null,
  -- Identifies "the same reminder" (e.g. due_24h:{assignment_id}:{due_at}) so it is
  -- never sent twice.
  dedupe_key text not null,
  title text,
  body text,
  error text,
  provider_message_id text,
  created_at timestamptz not null default now()
);

create index notification_log_user_created_idx on public.notification_log (user_id, created_at desc);
create index notification_log_user_dedupe_idx on public.notification_log (user_id, dedupe_key);

-- Triggers ---------------------------------------------------------------------

create trigger notification_tokens_set_updated_at before update on public.notification_tokens
for each row execute function public.set_updated_at();
create trigger notification_prefs_set_updated_at before update on public.notification_prefs
for each row execute function public.set_updated_at();

-- Every profile gets default preferences.
create or replace function public.create_default_notification_prefs()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.notification_prefs (user_id) values (new.id) on conflict do nothing;
  return new;
end;
$$;

revoke execute on function public.create_default_notification_prefs() from public, anon, authenticated;

create trigger profiles_create_notification_prefs
after insert on public.profiles
for each row execute function public.create_default_notification_prefs();

-- RLS ------------------------------------------------------------------------------

alter table public.notification_tokens enable row level security;
alter table public.notification_prefs enable row level security;
alter table public.notification_log enable row level security;

-- Tokens: registration goes through a server function (so a device can move between
-- accounts); clients can list and remove their own.
create policy "Users can view their own push tokens"
on public.notification_tokens for select to authenticated
using ((select auth.uid()) = user_id);

create policy "Users can delete their own push tokens"
on public.notification_tokens for delete to authenticated
using ((select auth.uid()) = user_id);

-- Prefs: read and edit your own row (created automatically).
create policy "Users can view their own notification prefs"
on public.notification_prefs for select to authenticated
using ((select auth.uid()) = user_id);

create policy "Users can update their own notification prefs"
on public.notification_prefs for update to authenticated
using ((select auth.uid()) = user_id)
with check ((select auth.uid()) = user_id);

-- Log: read-only history for the user; written by the service role.
create policy "Users can view their own notification log"
on public.notification_log for select to authenticated
using ((select auth.uid()) = user_id);

revoke all on public.notification_tokens, public.notification_prefs, public.notification_log from anon;
revoke insert, update on public.notification_tokens from authenticated;
revoke insert, delete on public.notification_prefs from authenticated;
revoke update on public.notification_prefs from authenticated;
grant update (
  push_enabled, email_digest_enabled, remind_24h, remind_2h, exam_countdown, morning_digest,
  morning_digest_time, quiet_hours_enabled, quiet_hours_start, quiet_hours_end, daily_cap
) on public.notification_prefs to authenticated;
revoke insert, update, delete on public.notification_log from authenticated;

-- ==== 20260924000900_subscriptions.sql
-- Billing subscriptions from Stripe (web) and RevenueCat (iOS/Android). Written only
-- by webhook handlers running as the service role; users can read their own.

create type public.billing_provider as enum ('stripe', 'revenuecat');
create type public.subscription_status as enum (
  'trialing', 'active', 'past_due', 'in_grace', 'paused', 'canceled', 'expired', 'refunded'
);

create table public.subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  provider public.billing_provider not null,
  -- Stripe subscription id (sub_...) or RevenueCat original transaction id.
  provider_subscription_id text not null,
  provider_customer_id text,
  product_id text,
  status public.subscription_status not null,
  current_period_end timestamptz,
  cancel_at_period_end boolean not null default false,
  -- Billing-retry window during which access continues after a failed renewal.
  grace_period_ends_at timestamptz,
  canceled_at timestamptz,
  -- Provider timestamp of the event that produced this state; older events are ignored.
  provider_updated_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint subscriptions_provider_subscription_key unique (provider, provider_subscription_id)
);

create index subscriptions_user_idx on public.subscriptions (user_id);

alter table public.subscriptions enable row level security;

create trigger subscriptions_set_updated_at before update on public.subscriptions
for each row execute function public.set_updated_at();

create policy "Users can view their own subscriptions"
on public.subscriptions for select to authenticated
using ((select auth.uid()) = user_id);

-- No write policies, and no write privileges: only service_role (which bypasses RLS)
-- can insert, update, or delete.
revoke all on public.subscriptions from anon;
revoke insert, update, delete, truncate on public.subscriptions from authenticated;

-- ==== 20260924001000_syllabus_upload_dedupe.sql
-- At most one live upload per stored file, so concurrent retries of upload-syllabus
-- can't start two parses. A failed upload may be retried with a new row.
create unique index syllabus_uploads_active_file_key
on public.syllabus_uploads (file_path)
where file_path is not null and status <> 'failed';

-- ==== 20260924001100_syllabus_extracted_text.sql
-- Keep the normalized text the parser saw, so uploads can be reparsed (new prompt
-- versions, evals) without re-running OCR.
create type public.syllabus_extraction_method as enum ('text_layer', 'ocr', 'pasted', 'url');

alter table public.syllabus_uploads
  add column extracted_text text,
  add column extraction_method public.syllabus_extraction_method,
  add column page_count integer check (page_count is null or page_count > 0);

-- ==== 20260924001200_syllabus_term_hints.sql
-- Term dates the student entered when uploading. Passed to the parser prompt and
-- preferred over dates found in the syllabus.
alter table public.syllabus_uploads
  add column term_start_hint date,
  add column term_end_hint date,
  add constraint syllabus_uploads_term_hint_order
    check (term_start_hint is null or term_end_hint is null or term_end_hint >= term_start_hint);

-- ==== 20260924001300_syllabus_ai_usage.sql
-- Token usage of every AI call made for an upload (OCR + parse attempts), for cost
-- tracking per user.
alter table public.syllabus_uploads
  add column ai_usage jsonb not null default '[]'::jsonb check (jsonb_typeof(ai_usage) = 'array');

-- ==== 20260924001400_commit_parsed_syllabus.sql
-- commit_parsed_syllabus: turns a reviewed parse result into a course, its grade
-- categories, and its assignments in one transaction.
--
-- Called by clients through PostgREST: supabase.rpc('commit_parsed_syllabus', {...}).
-- The function runs as the caller (security invoker), so RLS, check constraints, and
-- triggers apply to every insert exactly as for direct writes. Only claiming and
-- marking the upload row uses the security-definer helpers below, because clients
-- have no write access to syllabus_uploads.
--
-- p_payload is the (possibly edited) parse result; null means "use the stored
-- parse_result as is". Shape (extra keys are ignored):
--   {
--     "course": { "name", "code"?, "instructor"?, "term_start"?, "term_end"?,
--                 "target_grade"?, "color"? },
--     "categories": [ { "name", "weight" } ],
--     "assignments": [ { "title", "kind"?, "category_name"?, "due_at"?,
--                        "points_possible"?, "estimated_minutes"? } ]
--   }
--
-- Idempotent: committing an already-committed upload returns the same course id.

-- Locks the caller's upload for the rest of the transaction and returns its state.
create or replace function private.claim_upload_for_commit(p_upload_id uuid)
returns table (status public.syllabus_upload_status, course_id uuid, parse_result jsonb)
language plpgsql
security definer
set search_path = ''
as $$
begin
  return query
    select u.status, u.course_id, u.parse_result
    from public.syllabus_uploads u
    where u.id = p_upload_id
      and u.user_id = (select auth.uid())
    for update;
end;
$$;

create or replace function private.mark_upload_committed(p_upload_id uuid, p_course_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.syllabus_uploads
  set status = 'committed', course_id = p_course_id
  where id = p_upload_id
    and user_id = (select auth.uid())
    and status = 'parsed';
  if not found then
    raise exception 'upload % could not be marked committed', p_upload_id;
  end if;
end;
$$;

revoke execute on function private.claim_upload_for_commit(uuid) from public, anon;
revoke execute on function private.mark_upload_committed(uuid, uuid) from public, anon;
grant execute on function private.claim_upload_for_commit(uuid) to authenticated;
grant execute on function private.mark_upload_committed(uuid, uuid) to authenticated;

create or replace function public.commit_parsed_syllabus(p_upload_id uuid, p_payload jsonb default null)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_upload record;
  v_payload jsonb;
  v_course jsonb;
  v_course_id uuid;
  v_categories jsonb;
  v_assignments jsonb;
  v_bad text;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select * into v_upload from private.claim_upload_for_commit(p_upload_id);
  if not found then
    raise exception 'syllabus upload % not found', p_upload_id using errcode = 'P0002';
  end if;
  if v_upload.status = 'committed' and v_upload.course_id is not null then
    return v_upload.course_id; -- retry of a successful commit
  end if;
  if v_upload.status <> 'parsed' then
    raise exception 'syllabus upload is %, not parsed', v_upload.status using errcode = '55000';
  end if;

  v_payload := coalesce(p_payload, v_upload.parse_result);
  v_course := v_payload -> 'course';
  v_categories := coalesce(v_payload -> 'categories', '[]'::jsonb);
  v_assignments := coalesce(v_payload -> 'assignments', '[]'::jsonb);

  -- Shape checks with clear messages; column constraints catch the rest.
  if jsonb_typeof(v_course) is distinct from 'object' then
    raise exception 'payload.course must be an object' using errcode = '22023';
  end if;
  if jsonb_typeof(v_categories) <> 'array' or jsonb_typeof(v_assignments) <> 'array' then
    raise exception 'payload.categories and payload.assignments must be arrays' using errcode = '22023';
  end if;
  if jsonb_array_length(v_categories) > 30 or jsonb_array_length(v_assignments) > 500 then
    raise exception 'too many categories or assignments' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_categories) c
    where jsonb_typeof(c) <> 'object' or nullif(trim(c ->> 'name'), '') is null
  ) then
    raise exception 'every category needs a name' using errcode = '22023';
  end if;
  if exists (
    select lower(trim(c ->> 'name')) from jsonb_array_elements(v_categories) c
    group by 1 having count(*) > 1
  ) then
    raise exception 'category names must be unique' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_assignments) a
    where jsonb_typeof(a) <> 'object' or nullif(trim(a ->> 'title'), '') is null
  ) then
    raise exception 'every assignment needs a title' using errcode = '22023';
  end if;
  select a ->> 'category_name' into v_bad
  from jsonb_array_elements(v_assignments) a
  where nullif(trim(a ->> 'category_name'), '') is not null
    and not exists (
      select 1 from jsonb_array_elements(v_categories) c
      where lower(trim(c ->> 'name')) = lower(trim(a ->> 'category_name'))
    )
  limit 1;
  if v_bad is not null then
    raise exception 'assignment category "%" is not in categories', v_bad using errcode = '22023';
  end if;

  -- Course
  insert into public.courses (user_id, name, code, instructor, term_start, term_end, target_grade, color)
  values (
    v_user_id,
    trim(v_course ->> 'name'),
    nullif(trim(v_course ->> 'code'), ''),
    nullif(trim(v_course ->> 'instructor'), ''),
    (v_course ->> 'term_start')::date,
    (v_course ->> 'term_end')::date,
    (v_course ->> 'target_grade')::numeric,
    nullif(v_course ->> 'color', '')
  )
  returning id into v_course_id;

  -- Categories (weight null means "unknown"; store 0 so the student fills it in)
  insert into public.grade_categories (course_id, name, weight, position)
  select v_course_id, trim(c.value ->> 'name'), coalesce((c.value ->> 'weight')::numeric, 0), (c.ordinality - 1)::smallint
  from jsonb_array_elements(v_categories) with ordinality as c;

  -- Assignments, linked to categories by case-insensitive name
  insert into public.assignments (
    course_id, category_id, title, kind, due_at, points_possible, estimated_minutes, source
  )
  select
    v_course_id,
    gc.id,
    trim(a ->> 'title'),
    coalesce(nullif(a ->> 'kind', ''), 'assignment')::public.assignment_kind,
    (a ->> 'due_at')::timestamptz,
    (a ->> 'points_possible')::numeric,
    (a ->> 'estimated_minutes')::integer,
    'syllabus'
  from jsonb_array_elements(v_assignments) a
  left join public.grade_categories gc
    on gc.course_id = v_course_id
   and lower(gc.name) = lower(trim(a ->> 'category_name'));

  perform private.mark_upload_committed(p_upload_id, v_course_id);
  return v_course_id;
end;
$$;

revoke execute on function public.commit_parsed_syllabus(uuid, jsonb) from public, anon;
grant execute on function public.commit_parsed_syllabus(uuid, jsonb) to authenticated;

-- ==== 20260924001500_parse_limits.sql
-- Server-side syllabus parse quotas and Pro-only parse sources.
--
-- Limits live in private.parse_limits() (single source of truth; packages/core/src/plans
-- mirrors them for display). Enforcement is a BEFORE INSERT trigger on
-- syllabus_uploads that locks the user's profile row, so concurrent uploads can't
-- both squeeze under the limit. "Today" is the user's local day (profiles.timezone).
--
-- An upload counts toward the quota unless it failed before any AI call was made
-- (e.g. a bad file), so users aren't charged for our validation errors but can't get
-- free AI work by forcing failures.
--
-- Plan tier comes from profiles.plan_tier for now; the billing prompts replace this
-- with is_pro(user_id).

create or replace function private.parse_limits(p_tier public.plan_tier)
returns table (daily_parses integer, allowed_sources public.syllabus_source[], ocr_allowed boolean)
language sql
immutable
set search_path = ''
as $$
  select l.daily_parses, l.allowed_sources, l.ocr_allowed from (values
    ('free'::public.plan_tier, 3, array['pdf', 'text']::public.syllabus_source[], false),
    ('pro'::public.plan_tier, 25, array['pdf', 'image', 'text', 'url']::public.syllabus_source[], true)
  ) as l(tier, daily_parses, allowed_sources, ocr_allowed)
  where l.tier = p_tier;
$$;

-- Uploads that count toward the user's quota since their local midnight.
create or replace function private.parses_today(p_user_id uuid, p_timezone text)
returns integer
language sql
stable
set search_path = ''
as $$
  select count(*)::integer
  from public.syllabus_uploads u
  where u.user_id = p_user_id
    and u.created_at >= (date_trunc('day', now() at time zone p_timezone) at time zone p_timezone)
    and (u.status <> 'failed' or jsonb_array_length(u.ai_usage) > 0);
$$;

create or replace function private.enforce_parse_limits()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tier public.plan_tier;
  v_timezone text;
  v_limits record;
  v_used integer;
begin
  -- Lock the profile row: serializes concurrent uploads by the same user.
  select p.plan_tier, p.timezone into v_tier, v_timezone
  from public.profiles p
  where p.id = new.user_id
  for update;

  select * into v_limits from private.parse_limits(coalesce(v_tier, 'free'));

  if not (new.source = any (v_limits.allowed_sources)) then
    raise exception 'Importing from % requires StudyPulse Pro', new.source
      using errcode = 'SPP01', hint = 'pro_required';
  end if;

  v_used := private.parses_today(new.user_id, coalesce(v_timezone, 'UTC'));
  if v_used >= v_limits.daily_parses then
    raise exception 'Daily syllabus limit reached (% per day)', v_limits.daily_parses
      using errcode = 'SPL01', hint = 'parse_limit_reached';
  end if;

  return new;
end;
$$;

create trigger syllabus_uploads_enforce_limits
before insert on public.syllabus_uploads
for each row execute function private.enforce_parse_limits();

-- Quota for the current user, for the upload screen.
create or replace function public.get_parse_quota()
returns table (
  plan_tier public.plan_tier,
  daily_limit integer,
  used_today integer,
  remaining integer,
  allowed_sources public.syllabus_source[],
  ocr_allowed boolean
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_tier public.plan_tier;
  v_timezone text;
  v_used integer;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select p.plan_tier, p.timezone into v_tier, v_timezone from public.profiles p where p.id = v_user_id;
  v_used := private.parses_today(v_user_id, coalesce(v_timezone, 'UTC'));
  return query
    select coalesce(v_tier, 'free'), l.daily_parses, v_used, greatest(l.daily_parses - v_used, 0), l.allowed_sources, l.ocr_allowed
    from private.parse_limits(coalesce(v_tier, 'free')) l;
end;
$$;

-- Parse entitlements for a user, for server-side checks the trigger can't make (the
-- pipeline only learns a PDF needs OCR after extracting it). Service role only.
create or replace function public.parse_entitlements(p_user_id uuid)
returns table (plan_tier public.plan_tier, ocr_allowed boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select p.plan_tier, l.ocr_allowed
  from public.profiles p, private.parse_limits(p.plan_tier) l
  where p.id = p_user_id;
$$;

revoke execute on function private.enforce_parse_limits() from public, anon, authenticated;
revoke execute on function public.parse_entitlements(uuid) from public, anon, authenticated;
grant execute on function public.parse_entitlements(uuid) to service_role;
revoke execute on function public.get_parse_quota() from public, anon;
grant execute on function public.get_parse_quota() to authenticated;

-- ==== 20260924001600_drop_lowest_letter_scale.sql
-- Drop-lowest-N per grade category and an optional custom letter-grade scale per course.

alter table public.grade_categories
  add column drop_lowest smallint not null default 0
    constraint grade_categories_drop_lowest_range check (drop_lowest between 0 and 20);

-- A letter scale is a non-empty array of {"letter": "A-", "min": 90} with unique
-- letters and strictly descending minimums between 0 and 100.
create or replace function public.is_valid_letter_scale(scale jsonb)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  entry jsonb;
  prev numeric := null;
  letters text[] := '{}';
  letter text;
  min_value numeric;
begin
  if scale is null then
    return true;
  end if;
  if jsonb_typeof(scale) <> 'array' or jsonb_array_length(scale) = 0 or jsonb_array_length(scale) > 20 then
    return false;
  end if;
  for entry in select value from jsonb_array_elements(scale) loop
    if jsonb_typeof(entry) <> 'object' or jsonb_typeof(entry -> 'min') <> 'number'
       or jsonb_typeof(entry -> 'letter') <> 'string' then
      return false;
    end if;
    letter := trim(entry ->> 'letter');
    min_value := (entry ->> 'min')::numeric;
    if letter = '' or char_length(letter) > 5 or letter = any (letters)
       or min_value < 0 or min_value > 100 or (prev is not null and min_value >= prev) then
      return false;
    end if;
    letters := letters || letter;
    prev := min_value;
  end loop;
  return true;
end;
$$;

alter table public.courses
  add column letter_scale jsonb
    constraint courses_letter_scale_valid check (public.is_valid_letter_scale(letter_scale));

comment on column public.courses.letter_scale is
  'Custom letter scale, e.g. [{"letter":"A","min":93},...]; null uses the default scale.';

-- commit_parsed_syllabus also stores drop_lowest per category and the course's
-- letter scale (payload.course.letter_scale). Same function otherwise.
create or replace function public.commit_parsed_syllabus(p_upload_id uuid, p_payload jsonb default null)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_upload record;
  v_payload jsonb;
  v_course jsonb;
  v_course_id uuid;
  v_categories jsonb;
  v_assignments jsonb;
  v_bad text;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select * into v_upload from private.claim_upload_for_commit(p_upload_id);
  if not found then
    raise exception 'syllabus upload % not found', p_upload_id using errcode = 'P0002';
  end if;
  if v_upload.status = 'committed' and v_upload.course_id is not null then
    return v_upload.course_id; -- retry of a successful commit
  end if;
  if v_upload.status <> 'parsed' then
    raise exception 'syllabus upload is %, not parsed', v_upload.status using errcode = '55000';
  end if;

  v_payload := coalesce(p_payload, v_upload.parse_result);
  v_course := v_payload -> 'course';
  v_categories := coalesce(v_payload -> 'categories', '[]'::jsonb);
  v_assignments := coalesce(v_payload -> 'assignments', '[]'::jsonb);

  -- Shape checks with clear messages; column constraints catch the rest.
  if jsonb_typeof(v_course) is distinct from 'object' then
    raise exception 'payload.course must be an object' using errcode = '22023';
  end if;
  if jsonb_typeof(v_categories) <> 'array' or jsonb_typeof(v_assignments) <> 'array' then
    raise exception 'payload.categories and payload.assignments must be arrays' using errcode = '22023';
  end if;
  if jsonb_array_length(v_categories) > 30 or jsonb_array_length(v_assignments) > 500 then
    raise exception 'too many categories or assignments' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_categories) c
    where jsonb_typeof(c) <> 'object' or nullif(trim(c ->> 'name'), '') is null
  ) then
    raise exception 'every category needs a name' using errcode = '22023';
  end if;
  if exists (
    select lower(trim(c ->> 'name')) from jsonb_array_elements(v_categories) c
    group by 1 having count(*) > 1
  ) then
    raise exception 'category names must be unique' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_assignments) a
    where jsonb_typeof(a) <> 'object' or nullif(trim(a ->> 'title'), '') is null
  ) then
    raise exception 'every assignment needs a title' using errcode = '22023';
  end if;
  select a ->> 'category_name' into v_bad
  from jsonb_array_elements(v_assignments) a
  where nullif(trim(a ->> 'category_name'), '') is not null
    and not exists (
      select 1 from jsonb_array_elements(v_categories) c
      where lower(trim(c ->> 'name')) = lower(trim(a ->> 'category_name'))
    )
  limit 1;
  if v_bad is not null then
    raise exception 'assignment category "%" is not in categories', v_bad using errcode = '22023';
  end if;

  -- Course
  insert into public.courses (user_id, name, code, instructor, term_start, term_end, target_grade, color, letter_scale)
  values (
    v_user_id,
    trim(v_course ->> 'name'),
    nullif(trim(v_course ->> 'code'), ''),
    nullif(trim(v_course ->> 'instructor'), ''),
    (v_course ->> 'term_start')::date,
    (v_course ->> 'term_end')::date,
    (v_course ->> 'target_grade')::numeric,
    nullif(v_course ->> 'color', ''),
    nullif(v_course -> 'letter_scale', 'null'::jsonb)
  )
  returning id into v_course_id;

  -- Categories (weight null means "unknown"; store 0 so the student fills it in)
  insert into public.grade_categories (course_id, name, weight, drop_lowest, position)
  select
    v_course_id,
    trim(c.value ->> 'name'),
    coalesce((c.value ->> 'weight')::numeric, 0),
    coalesce((c.value ->> 'drop_lowest')::smallint, 0),
    (c.ordinality - 1)::smallint
  from jsonb_array_elements(v_categories) with ordinality as c;

  -- Assignments, linked to categories by case-insensitive name
  insert into public.assignments (
    course_id, category_id, title, kind, due_at, points_possible, estimated_minutes, source
  )
  select
    v_course_id,
    gc.id,
    trim(a ->> 'title'),
    coalesce(nullif(a ->> 'kind', ''), 'assignment')::public.assignment_kind,
    (a ->> 'due_at')::timestamptz,
    (a ->> 'points_possible')::numeric,
    (a ->> 'estimated_minutes')::integer,
    'syllabus'
  from jsonb_array_elements(v_assignments) a
  left join public.grade_categories gc
    on gc.course_id = v_course_id
   and lower(gc.name) = lower(trim(a ->> 'category_name'));

  perform private.mark_upload_committed(p_upload_id, v_course_id);
  return v_course_id;
end;
$$;

-- ==== 20260924001700_task_priority.sql
-- SQL mirror of packages/core/src/priority (priority() and gradeShare()), used by the
-- Today feed RPC. Parity with the TypeScript version is pinned by
-- supabase/tests/database/130_priority_parity.test.sql, generated from core fixtures.

create or replace function public.task_priority(
  p_grade_share numeric,
  p_due_at timestamptz,
  p_now timestamptz,
  p_minutes_remaining numeric,
  p_status public.assignment_status,
  p_daily_minutes numeric default 120
)
returns numeric
language plpgsql
immutable
parallel safe
set search_path = ''
as $$
declare
  v_daily numeric := case when p_daily_minutes > 0 then p_daily_minutes else 120 end;
  v_impact numeric := sqrt(least(1, greatest(0, greatest(0, p_grade_share) / 30.0)));
  v_days numeric;
  v_work_days numeric := greatest(0, p_minutes_remaining) / v_daily;
  v_urgency numeric;
  v_score numeric;
begin
  if p_status in ('done', 'skipped') then
    return 0;
  end if;
  if p_due_at is null then
    v_urgency := 0.05;
  else
    v_days := extract(epoch from (p_due_at - p_now)) / 86400.0;
    v_urgency := case when v_days <= 0 then 1 else 1 / (1 + greatest(0, v_days - v_work_days)) end;
  end if;
  v_score := 0.55 * v_impact + 0.45 * v_urgency;
  if p_status = 'in_progress' then
    v_score := v_score * 1.1;
  end if;
  return round(least(1, v_score) * 100, 3);
end;
$$;

-- Share of the final grade per assignment (percent), mirroring gradeShare().
create or replace view public.assignment_grade_shares
with (security_invoker = true)
as
with cat as (
  select gc.id, gc.course_id, greatest(gc.weight, 0) as weight,
         sum(greatest(gc.weight, 0)) over (partition by gc.course_id) as total_weight
  from public.grade_categories gc
),
course_has_categories as (
  select c.id as course_id, exists (select 1 from public.grade_categories g where g.course_id = c.id) as has_categories
  from public.courses c
),
avg_points as (
  -- average points of items with points, per category (null category = whole course)
  select a.course_id, a.category_id, avg(a.points_possible) filter (where a.points_possible > 0) as avg_possible
  from public.assignments a
  group by a.course_id, a.category_id
),
course_avg as (
  select a.course_id, avg(a.points_possible) filter (where a.points_possible > 0) as avg_possible
  from public.assignments a
  group by a.course_id
),
pts as (
  select
    a.id, a.course_id, a.category_id, chc.has_categories,
    case
      when a.points_possible > 0 then a.points_possible
      when chc.has_categories then coalesce(ap.avg_possible, 1)
      else coalesce(ca.avg_possible, 1)
    end as points
  from public.assignments a
  join course_has_categories chc on chc.course_id = a.course_id
  left join avg_points ap on ap.course_id = a.course_id and ap.category_id is not distinct from a.category_id
  left join course_avg ca on ca.course_id = a.course_id
)
select
  p.id as assignment_id,
  p.course_id,
  case
    when not p.has_categories then
      p.points / nullif(sum(p.points) over (partition by p.course_id), 0) * 100
    when cat.id is null or cat.weight <= 0 or cat.total_weight <= 0 then 0
    else (cat.weight / cat.total_weight) * p.points / nullif(sum(p.points) over (partition by p.course_id, p.category_id), 0) * 100
  end as grade_share
from pts p
left join cat on cat.id = p.category_id;

grant select on public.assignment_grade_shares to authenticated;
revoke all on public.assignment_grade_shares from anon;

-- ==== 20260924001800_today_feed.sql
-- Today feed: ranked tasks for the user's local day, capped by their study minutes.

-- How long the student can study per day. Per-weekday overrides (Sunday first) take
-- precedence when set; null entries fall back to the daily default.
alter table public.profiles
  add column daily_study_minutes smallint not null default 120
    constraint profiles_daily_study_minutes_range check (daily_study_minutes between 0 and 960),
  add column study_minutes_by_weekday smallint[]
    constraint profiles_study_minutes_by_weekday_shape check (
      study_minutes_by_weekday is null
      or (array_length(study_minutes_by_weekday, 1) = 7
          and 0 <= all (study_minutes_by_weekday) and 960 >= all (study_minutes_by_weekday))
    );

grant update (daily_study_minutes, study_minutes_by_weekday) on public.profiles to authenticated;

-- Effort to assume when a task has no estimate. Mirrors DEFAULT_MINUTES_BY_KIND in
-- packages/core/src/priority (pinned by 150_today_feed.test.sql).
create or replace function public.default_task_minutes(p_kind public.assignment_kind)
returns integer
language sql
immutable
parallel safe
set search_path = ''
as $$
  select case p_kind
    when 'exam' then 240
    when 'project' then 300
    when 'assignment' then 90
    when 'lab' then 120
    when 'quiz' then 45
    when 'reading' then 45
    when 'discussion' then 30
    else 60
  end;
$$;

-- Minutes the user can study on a local date.
create or replace function public.study_capacity(p_user_id uuid, p_date date)
returns integer
language sql
stable
set search_path = ''
as $$
  select coalesce(p.study_minutes_by_weekday[extract(dow from p_date)::integer + 1], p.daily_study_minutes)::integer
  from public.profiles p
  where p.id = p_user_id;
$$;

create or replace function public.get_today_feed(p_date date default null)
returns table (
  assignment_id uuid,
  course_id uuid,
  course_name text,
  title text,
  kind public.assignment_kind,
  status public.assignment_status,
  due_at timestamptz,
  grade_share numeric,
  minutes_remaining integer,
  planned_minutes integer,
  priority numeric,
  overdue boolean,
  rank integer,
  -- Capacity for the day (same on every row) so one call renders the header too.
  capacity_minutes integer,
  studied_minutes integer
)
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_tz text;
  v_date date;
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_now timestamptz := now();
  v_capacity integer;
  v_daily integer;
  v_studied integer;
  v_left integer;
  r record;
  v_rank integer := 0;
  v_planned integer;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select p.timezone, p.daily_study_minutes into v_tz, v_daily from public.profiles p where p.id = v_user_id;
  v_date := coalesce(p_date, (v_now at time zone v_tz)::date);
  v_day_start := v_date::timestamp at time zone v_tz;
  v_day_end := (v_date + 1)::timestamp at time zone v_tz;
  v_capacity := coalesce(public.study_capacity(v_user_id, v_date), 120);

  -- Time already studied today counts against the day's capacity.
  select coalesce(sum(extract(epoch from (least(coalesce(s.ended_at, v_now), v_day_end) - greatest(s.started_at, v_day_start))) / 60), 0)::integer
  into v_studied
  from public.study_sessions s
  where s.user_id = v_user_id
    and s.started_at < v_day_end
    and coalesce(s.ended_at, v_now) > v_day_start;

  v_left := greatest(v_capacity - v_studied, 0);

  for r in
    with logged as (
      select s.assignment_id, sum(coalesce(s.duration_minutes, 0)) as minutes
      from public.study_sessions s
      where s.user_id = v_user_id and s.assignment_id is not null
      group by s.assignment_id
    ),
    candidates as (
      select
        a.id, a.course_id, c.name as course_name, a.title, a.kind, a.status, a.due_at,
        coalesce(gs.grade_share, 0) as grade_share,
        greatest(coalesce(a.estimated_minutes, public.default_task_minutes(a.kind)) - coalesce(l.minutes, 0), 0)::integer as minutes_remaining
      from public.assignments a
      join public.courses c on c.id = a.course_id
      left join public.assignment_grade_shares gs on gs.assignment_id = a.id
      left join logged l on l.assignment_id = a.id
      where c.user_id = v_user_id
        and c.archived_at is null
        and a.status in ('todo', 'in_progress')
        and (a.due_at is null or a.due_at between v_day_start - interval '7 days' and v_day_end + interval '30 days')
    )
    select
      cand.*,
      public.task_priority(cand.grade_share, cand.due_at, v_now, cand.minutes_remaining, cand.status, coalesce(v_daily, 120)) as score
    from candidates cand
    where cand.minutes_remaining > 0
    order by score desc, cand.due_at nulls last, cand.title
  loop
    exit when v_left <= 0;
    -- Today's fair share of the task: everything if it's due by the end of today,
    -- otherwise the remaining minutes spread over the days left (at least 25 minutes
    -- so work sessions stay meaningful).
    if r.due_at is null then
      v_planned := least(r.minutes_remaining, 30);
    elsif r.due_at <= v_day_end then
      v_planned := r.minutes_remaining;
    else
      v_planned := least(
        r.minutes_remaining,
        greatest(25, ceil(r.minutes_remaining / greatest(1, ceil(extract(epoch from (r.due_at - v_day_start)) / 86400)))::integer)
      );
    end if;
    v_planned := least(v_planned, v_left);
    continue when v_planned < 15 and v_planned < r.minutes_remaining; -- too small a slot to be useful
    v_left := v_left - v_planned;
    v_rank := v_rank + 1;

    assignment_id := r.id;
    course_id := r.course_id;
    course_name := r.course_name;
    title := r.title;
    kind := r.kind;
    status := r.status;
    due_at := r.due_at;
    grade_share := round(r.grade_share, 2);
    minutes_remaining := r.minutes_remaining;
    planned_minutes := v_planned;
    priority := r.score;
    overdue := r.due_at is not null and r.due_at < v_now;
    rank := v_rank;
    capacity_minutes := v_capacity;
    studied_minutes := v_studied;
    return next;
  end loop;
end;
$$;

revoke execute on function public.get_today_feed(date) from public, anon;
grant execute on function public.get_today_feed(date) to authenticated;

-- ==== 20260924001900_study_plan.sql
-- Persisting scheduler output. The scheduler itself is TypeScript
-- (packages/core/src/scheduler); this swaps a user's future scheduler-made blocks for a
-- new plan in one transaction.

alter table public.profiles
  add column study_start_time time not null default '16:00';

grant update (study_start_time) on public.profiles to authenticated;

-- p_blocks: [{ "assignment_id", "course_id", "starts_at", "ends_at", "kind" }]
-- Only future, unlocked, still-planned blocks created by the scheduler are replaced;
-- locked, manual, review-plan, done, and missed blocks are never touched.
create or replace function public.replace_study_plan(p_user_id uuid, p_from timestamptz, p_blocks jsonb)
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_inserted integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' and p_user_id is distinct from (select auth.uid()) then
    raise exception 'cannot replace another user''s plan' using errcode = '42501';
  end if;
  if jsonb_typeof(p_blocks) <> 'array' or jsonb_array_length(p_blocks) > 500 then
    raise exception 'p_blocks must be an array of at most 500 blocks' using errcode = '22023';
  end if;

  delete from public.study_blocks
  where user_id = p_user_id
    and starts_at >= p_from
    and status = 'planned'
    and not locked
    and source = 'scheduler';

  insert into public.study_blocks (user_id, course_id, assignment_id, starts_at, ends_at, kind, source)
  select
    p_user_id,
    (b ->> 'course_id')::uuid,
    (b ->> 'assignment_id')::uuid,
    (b ->> 'starts_at')::timestamptz,
    (b ->> 'ends_at')::timestamptz,
    coalesce(b ->> 'kind', 'study')::public.study_block_kind,
    'scheduler'
  from jsonb_array_elements(p_blocks) b
  where (b ->> 'starts_at')::timestamptz >= p_from;

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$$;

revoke execute on function public.replace_study_plan(uuid, timestamptz, jsonb) from public, anon;
grant execute on function public.replace_study_plan(uuid, timestamptz, jsonb) to authenticated, service_role;

-- ==== 20260924002000_nightly_replan.sql
-- Nightly maintenance of study plans: mark missed blocks, then (in the nightly-replan
-- edge function) re-rank and reschedule, and flag overloaded days.

-- Marks planned blocks that have ended. A block counts as done instead of missed when
-- the user logged study time in the same course overlapping at least half of it.
-- Returns one row per affected user. Service role only.
create or replace function public.mark_missed_blocks(p_before timestamptz default now())
returns table (user_id uuid, missed integer, done integer)
language plpgsql
security definer
set search_path = ''
as $$
begin
  return query
  with ended as (
    select b.id, b.user_id, b.course_id, b.starts_at, b.ends_at
    from public.study_blocks b
    where b.status = 'planned' and b.ends_at <= p_before
    for update skip locked
  ),
  coverage as (
    select e.id,
      -- filter: greatest()/least() ignore NULLs, so an unmatched row would count as full coverage
      coalesce(sum(extract(epoch from (least(e.ends_at, coalesce(s.ended_at, p_before)) - greatest(e.starts_at, s.started_at))))
        filter (where s.id is not null), 0)
        / extract(epoch from (e.ends_at - e.starts_at)) as covered
    from ended e
    left join public.study_sessions s
      on s.user_id = e.user_id
     and s.course_id = e.course_id
     and s.started_at < e.ends_at
     and coalesce(s.ended_at, p_before) > e.starts_at
    group by e.id, e.starts_at, e.ends_at
  ),
  updated as (
    update public.study_blocks b
    set status = case when c.covered >= 0.5 then 'done'::public.study_block_status else 'missed'::public.study_block_status end
    from coverage c
    where b.id = c.id
    returning b.user_id, b.status
  )
  select u.user_id,
         count(*) filter (where u.status = 'missed')::integer,
         count(*) filter (where u.status = 'done')::integer
  from updated u
  group by u.user_id;
end;
$$;

-- Users whose local time is p_local_hour (the nightly run) and who have something to
-- plan: open work due in the next four weeks, or future planned blocks.
create or replace function public.users_due_for_replan(p_local_hour integer default 3, p_now timestamptz default now())
returns table (user_id uuid, timezone text)
language sql
stable
security definer
set search_path = ''
as $$
  select p.id, p.timezone
  from public.profiles p
  where extract(hour from p_now at time zone p.timezone) = p_local_hour
    and (
      exists (
        select 1 from public.assignments a
        join public.courses c on c.id = a.course_id
        where c.user_id = p.id and c.archived_at is null
          and a.status in ('todo', 'in_progress')
          and a.due_at between p_now and p_now + interval '28 days'
      )
      or exists (
        select 1 from public.study_blocks b
        where b.user_id = p.id and b.status = 'planned' and b.starts_at > p_now
      )
    );
$$;

-- Overloaded days found by the last replan. The user can see them; notifications use
-- them to warn about days that can't fit the planned work.
create table public.study_plan_alerts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  local_date date not null,
  kind text not null default 'overloaded' check (kind in ('overloaded')),
  -- { "unscheduled_minutes": 90, "assignment_ids": [...] }
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint study_plan_alerts_user_date_kind_key unique (user_id, local_date, kind)
);

alter table public.study_plan_alerts enable row level security;

create policy "Users can view their own plan alerts"
on public.study_plan_alerts for select to authenticated
using ((select auth.uid()) = user_id);

revoke all on public.study_plan_alerts from anon;
revoke insert, update, delete on public.study_plan_alerts from authenticated;

-- Replaces a user's future alerts with the latest findings.
create or replace function public.set_plan_alerts(p_user_id uuid, p_from date, p_alerts jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.study_plan_alerts where user_id = p_user_id and local_date >= p_from;
  insert into public.study_plan_alerts (user_id, local_date, kind, details)
  select p_user_id, (a ->> 'local_date')::date, 'overloaded', coalesce(a -> 'details', '{}'::jsonb)
  from jsonb_array_elements(p_alerts) a
  on conflict (user_id, local_date, kind) do update set details = excluded.details, created_at = now();
end;
$$;

revoke execute on function public.mark_missed_blocks(timestamptz) from public, anon, authenticated;
revoke execute on function public.users_due_for_replan(integer, timestamptz) from public, anon, authenticated;
revoke execute on function public.set_plan_alerts(uuid, date, jsonb) from public, anon, authenticated;
grant execute on function public.mark_missed_blocks(timestamptz) to service_role;
grant execute on function public.users_due_for_replan(integer, timestamptz) to service_role;
grant execute on function public.set_plan_alerts(uuid, date, jsonb) to service_role;

-- Scheduling ------------------------------------------------------------------------
-- pg_cron calls edge functions through pg_net. The project URL and the shared cron
-- secret come from Vault, so no environment-specific values live in migrations:
--   select vault.create_secret('https://<ref>.supabase.co', 'project_url');
--   select vault.create_secret('<random>', 'cron_secret');   -- same as CRON_SECRET
-- Without those secrets the job is a no-op (e.g. local dev).
create extension if not exists pg_cron with schema pg_catalog;
create extension if not exists pg_net with schema extensions;

create or replace function private.invoke_edge_function(p_name text, p_body jsonb default '{}'::jsonb)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_url text;
  v_secret text;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'project_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'cron_secret';
  if v_url is null or v_secret is null then
    raise notice 'invoke_edge_function(%): project_url/cron_secret not in vault; skipping', p_name;
    return null;
  end if;
  return net.http_post(
    url := v_url || '/functions/v1/' || p_name,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', v_secret),
    body := p_body,
    timeout_milliseconds := 5000
  );
end;
$$;

revoke execute on function private.invoke_edge_function(text, jsonb) from public, anon, authenticated;

-- Hourly: each run replans the users for whom it's 3 AM.
select cron.schedule('nightly-replan', '5 * * * *', $$ select private.invoke_edge_function('nightly-replan') $$);

-- ==== 20260924002100_review_plan.sql
-- Exam review plans (packages/core/src/review): swaps the future, unlocked, still-planned
-- review_plan blocks of the given exams for a freshly generated set. Blocks the user
-- moved (locked) or finished stay.
create or replace function public.replace_review_plan(
  p_user_id uuid,
  p_from timestamptz,
  p_assignment_ids uuid[],
  p_blocks jsonb
)
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_inserted integer;
  v_tz text;
begin
  if coalesce(auth.role(), '') <> 'service_role' and p_user_id is distinct from (select auth.uid()) then
    raise exception 'cannot replace another user''s review plan' using errcode = '42501';
  end if;
  if jsonb_typeof(p_blocks) <> 'array' or jsonb_array_length(p_blocks) > 300 then
    raise exception 'p_blocks must be an array of at most 300 blocks' using errcode = '22023';
  end if;

  select coalesce((select timezone from public.profiles where id = p_user_id), 'UTC') into v_tz;

  delete from public.study_blocks
  where user_id = p_user_id
    and source = 'review_plan'
    and status = 'planned'
    and not locked
    and starts_at >= p_from
    and (assignment_id = any (p_assignment_ids) or assignment_id is null);

  -- Keep a locked/finished review for the same exam and day instead of duplicating it.
  insert into public.study_blocks (user_id, course_id, assignment_id, starts_at, ends_at, kind, source)
  select p_user_id, (b ->> 'course_id')::uuid, (b ->> 'assignment_id')::uuid,
         (b ->> 'starts_at')::timestamptz, (b ->> 'ends_at')::timestamptz, 'review', 'review_plan'
  from jsonb_array_elements(p_blocks) b
  where (b ->> 'starts_at')::timestamptz >= p_from
    and not exists (
      select 1 from public.study_blocks kept
      where kept.user_id = p_user_id
        and kept.source = 'review_plan'
        and kept.assignment_id = (b ->> 'assignment_id')::uuid
        -- same local day for the user, not the same UTC day
        and (kept.starts_at at time zone v_tz)::date = ((b ->> 'starts_at')::timestamptz at time zone v_tz)::date
    );

  get diagnostics v_inserted = row_count;
  return v_inserted;
end;
$$;

revoke execute on function public.replace_review_plan(uuid, timestamptz, uuid[], jsonb) from public, anon;
grant execute on function public.replace_review_plan(uuid, timestamptz, uuid[], jsonb) to authenticated, service_role;

-- ==== 20260924002200_flashcards.sql
-- Flashcards for review, exportable to Anki and Quizlet. Owned through their course,
-- like other child tables.
create table public.flashcards (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  assignment_id uuid references public.assignments (id) on delete set null,
  front text not null check (char_length(trim(front)) between 1 and 2000),
  back text not null check (char_length(trim(back)) between 1 and 5000),
  tags text[] not null default '{}' check (array_length(tags, 1) is null or array_length(tags, 1) <= 20),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index flashcards_course_idx on public.flashcards (course_id);
create index flashcards_assignment_idx on public.flashcards (assignment_id);

alter table public.flashcards enable row level security;

create trigger flashcards_set_updated_at before update on public.flashcards
for each row execute function public.set_updated_at();

create policy "Users can view cards in their courses"
on public.flashcards for select to authenticated
using ((select private.owns_course(course_id)));

create policy "Users can create cards in their courses"
on public.flashcards for insert to authenticated
with check ((select private.owns_course(course_id)));

create policy "Users can update cards in their courses"
on public.flashcards for update to authenticated
using ((select private.owns_course(course_id)))
with check ((select private.owns_course(course_id)));

create policy "Users can delete cards in their courses"
on public.flashcards for delete to authenticated
using ((select private.owns_course(course_id)));

revoke all on public.flashcards from anon;

-- ==== 20260924002300_weekly_focus_view.sql
-- Current grade in SQL (mirror of currentGrade() in packages/core/src/grades) and a
-- weekly focus-minutes view per course alongside it. Parity with TypeScript is pinned by
-- supabase/tests/database/190_grade_parity.test.sql, generated from core fixtures.

-- Best pooled percent keeping all but p_drop items (at least one kept), by the same
-- Kern-Bailey bisection as chooseDrops(). Arrays are aligned; returns null if empty.
create or replace function private.best_kept_percent(p_earned numeric[], p_possible numeric[], p_drop integer)
returns numeric
language plpgsql
immutable
set search_path = ''
as $$
declare
  n integer := coalesce(array_length(p_earned, 1), 0);
  k integer;
  lo numeric := 0;
  hi numeric := 0;
  q numeric;
  s numeric;
  i integer;
begin
  if n = 0 then
    return null;
  end if;
  k := n - least(greatest(coalesce(p_drop, 0), 0), n - 1);
  if k = n then
    return (select sum(e) / nullif(sum(p), 0) * 100 from unnest(p_earned, p_possible) as t(e, p));
  end if;
  select max(e / p) into hi from unnest(p_earned, p_possible) as t(e, p) where p > 0;
  hi := greatest(coalesce(hi, 0), 0);
  for i in 1..60 loop
    q := (lo + hi) / 2;
    select sum(v) into s
    from (select e - q * p as v from unnest(p_earned, p_possible) as t(e, p) order by 1 desc limit k) top;
    if s >= 0 then lo := q; else hi := q; end if;
  end loop;
  -- Percent of the best set at q = lo.
  return (
    select sum(e) / nullif(sum(p), 0) * 100
    from (select e, p from unnest(p_earned, p_possible) as t(e, p) order by e - lo * p desc limit k) best
  );
end;
$$;

-- Current grade of a course: pooled percent per category (after drop-lowest), weighted
-- average over categories that have grades, renormalized. No categories = one pool.
-- Runs as the caller, so RLS applies.
create or replace function public.course_current_grade(p_course_id uuid)
returns numeric
language sql
stable
security invoker
set search_path = ''
as $$
  with graded as (
    select a.category_id, a.points_earned as e, a.points_possible as p
    from public.assignments a
    where a.course_id = p_course_id
      and a.points_earned is not null and a.points_possible > 0
  ),
  per_category as (
    select gc.weight,
           private.best_kept_percent(array_agg(g.e), array_agg(g.p), gc.drop_lowest) as pct
    from public.grade_categories gc
    join graded g on g.category_id = gc.id
    where gc.course_id = p_course_id and gc.weight > 0
    group by gc.id, gc.weight, gc.drop_lowest
  )
  select case
    when exists (select 1 from public.grade_categories where course_id = p_course_id) then
      (select sum(weight * pct) / nullif(sum(weight), 0) from per_category where pct is not null)
    else
      (select sum(e) / nullif(sum(p), 0) * 100 from graded)
  end;
$$;

-- Letter for a percent from a course scale (or the default), mirroring letterFor().
create or replace function public.letter_for(p_percent numeric, p_scale jsonb default null)
returns text
language sql
immutable
set search_path = ''
as $$
  with scale as (
    select coalesce(p_scale, '[{"letter":"A","min":93},{"letter":"A-","min":90},{"letter":"B+","min":87},
      {"letter":"B","min":83},{"letter":"B-","min":80},{"letter":"C+","min":77},{"letter":"C","min":73},
      {"letter":"C-","min":70},{"letter":"D+","min":67},{"letter":"D","min":63},{"letter":"D-","min":60},
      {"letter":"F","min":0}]'::jsonb) as s
  ),
  entries as (
    select e ->> 'letter' as letter, (e ->> 'min')::numeric as min_value, ord
    from scale, jsonb_array_elements(scale.s) with ordinality as x(e, ord)
  )
  select case when p_percent is null then null else coalesce(
    (select letter from entries where round(p_percent, 2) >= min_value order by ord limit 1),
    (select letter from entries order by ord desc limit 1)
  ) end;
$$;

-- Weekly focus minutes per course (weeks start Monday in the user's timezone), with the
-- course's current grade and letter. Runs as the caller (RLS applies).
create or replace view public.weekly_focus_by_course
with (security_invoker = true)
as
select
  c.user_id,
  c.id as course_id,
  c.name as course_name,
  c.code as course_code,
  date_trunc('week', s.started_at at time zone p.timezone)::date as week_start,
  sum(s.duration_minutes)::integer as focus_minutes,
  count(*)::integer as session_count,
  round(public.course_current_grade(c.id), 2) as current_grade,
  public.letter_for(public.course_current_grade(c.id), c.letter_scale) as current_letter
from public.study_sessions s
join public.courses c on c.id = s.course_id
join public.profiles p on p.id = c.user_id
where s.ended_at is not null
group by c.user_id, c.id, c.name, c.code, c.letter_scale, 5;

grant select on public.weekly_focus_by_course to authenticated;
revoke all on public.weekly_focus_by_course from anon;
revoke execute on function private.best_kept_percent(numeric[], numeric[], integer) from public, anon;
grant execute on function private.best_kept_percent(numeric[], numeric[], integer) to authenticated, service_role;

-- ==== 20260924002400_study_session_endpoints.sql
-- Study session start/stop endpoints (RPCs). Idempotent via client-generated ids;
-- overlapping sessions are impossible (exclusion constraint), including a second
-- running session.

create extension if not exists btree_gist with schema extensions;

-- A running session occupies [started_at, infinity).
alter table public.study_sessions
  add constraint study_sessions_no_overlap
  exclude using gist (
    user_id with =,
    tstzrange(started_at, coalesce(ended_at, 'infinity'::timestamptz), '[)') with &&
  );

-- Start a session. p_id is generated by the client and reused on retries, so a retry
-- after a lost response returns the same session instead of failing or duplicating.
-- p_started_at lets an offline client report when it really started (within limits).
create or replace function public.start_study_session(
  p_id uuid,
  p_course_id uuid,
  p_assignment_id uuid default null,
  p_started_at timestamptz default null
)
returns public.study_sessions
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_started timestamptz := coalesce(p_started_at, now());
  v_session public.study_sessions;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select * into v_session from public.study_sessions where id = p_id;
  if found then
    if v_session.user_id <> v_user_id then
      raise exception 'session id already used' using errcode = '23505';
    end if;
    if v_session.course_id is distinct from coalesce(
         (select a.course_id from public.assignments a where a.id = p_assignment_id), p_course_id)
       or v_session.assignment_id is distinct from p_assignment_id then
      raise exception 'session % already exists with different details', p_id using errcode = '23505';
    end if;
    return v_session; -- idempotent retry
  end if;

  if v_started > now() + interval '5 minutes' then
    raise exception 'started_at is in the future' using errcode = '22023';
  end if;
  if v_started < now() - interval '24 hours' then
    raise exception 'started_at is more than 24 hours ago' using errcode = '22023';
  end if;

  begin
    insert into public.study_sessions (id, user_id, course_id, assignment_id, started_at, source)
    values (p_id, v_user_id, p_course_id, p_assignment_id, v_started, 'timer')
    returning * into v_session;
  exception when exclusion_violation then
    raise exception 'another study session overlaps this one; stop it first'
      using errcode = '23P01', hint = 'session_overlap';
  end;

  -- Working on it now: a to-do assignment becomes in progress.
  if p_assignment_id is not null then
    update public.assignments set status = 'in_progress' where id = p_assignment_id and status = 'todo';
  end if;

  return v_session;
end;
$$;

-- Stop a session. Idempotent: stopping an already-stopped session returns it unchanged.
create or replace function public.stop_study_session(p_id uuid, p_ended_at timestamptz default null)
returns public.study_sessions
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_session public.study_sessions;
  v_ended timestamptz := coalesce(p_ended_at, now());
begin
  if (select auth.uid()) is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select * into v_session from public.study_sessions where id = p_id for update;
  if not found then
    raise exception 'study session % not found', p_id using errcode = 'P0002';
  end if;
  if v_session.ended_at is not null then
    return v_session; -- idempotent retry
  end if;

  if v_ended > now() + interval '5 minutes' then
    raise exception 'ended_at is in the future' using errcode = '22023';
  end if;
  if v_ended <= v_session.started_at then
    raise exception 'ended_at must be after started_at' using errcode = '22023';
  end if;
  -- Forgotten timers are capped rather than rejected.
  v_ended := least(v_ended, v_session.started_at + interval '12 hours');

  begin
    update public.study_sessions set ended_at = v_ended where id = p_id returning * into v_session;
  exception when exclusion_violation then
    raise exception 'this session would overlap another one' using errcode = '23P01', hint = 'session_overlap';
  end;
  return v_session;
end;
$$;

revoke execute on function public.start_study_session(uuid, uuid, uuid, timestamptz) from public, anon;
revoke execute on function public.stop_study_session(uuid, timestamptz) from public, anon;
grant execute on function public.start_study_session(uuid, uuid, uuid, timestamptz) to authenticated;
grant execute on function public.stop_study_session(uuid, timestamptz) to authenticated;

